{
  "id": "umf.domain-pack",
  "version": "1.0.0",
  "coreVersion": "0.1.0",
  "description": "Portable sample-domain pack metadata with opaque implementation and schema references",
  "schema": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "urn:umf:domain-pack:1.0.0",
    "type": "object",
    "required": [
      "id",
      "version",
      "domain_types"
    ],
    "anyOf": [
      {
        "properties": {
          "generator": {}
        },
        "required": [
          "generator"
        ]
      },
      {
        "properties": {
          "sources": {}
        },
        "required": [
          "sources"
        ]
      }
    ],
    "properties": {
      "artifact_collections": {
        "type": "array",
        "maxItems": 64,
        "items": {
          "type": "object",
          "required": [
            "version",
            "id",
            "title",
            "view",
            "semantic_kinds",
            "source_ids"
          ],
          "properties": {
            "version": {
              "const": "1.0.0"
            },
            "id": {
              "type": "string",
              "pattern": "^[A-Za-z][A-Za-z0-9_-]*$"
            },
            "title": {
              "type": "string",
              "minLength": 1
            },
            "description": {
              "type": "string"
            },
            "view": {
              "enum": [
                "documents",
                "imaging",
                "other"
              ]
            },
            "semantic_kinds": {
              "type": "array",
              "maxItems": 10000,
              "uniqueItems": true,
              "items": {
                "type": "string",
                "minLength": 1
              },
              "minItems": 1
            },
            "source_ids": {
              "type": "array",
              "maxItems": 10000,
              "uniqueItems": true,
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "media_types": {
              "type": "array",
              "maxItems": 10000,
              "uniqueItems": true,
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "metadata_schema_ids": {
              "type": "array",
              "maxItems": 10000,
              "uniqueItems": true,
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "derived_schema_ids": {
              "type": "array",
              "maxItems": 10000,
              "uniqueItems": true,
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "ontology_schema_ids": {
              "type": "array",
              "maxItems": 10000,
              "uniqueItems": true,
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "loader_inventory_source_id": {
              "type": "string",
              "minLength": 1
            },
            "identity": {
              "type": "object",
              "required": [
                "description"
              ],
              "properties": {
                "description": {
                  "type": "string",
                  "minLength": 1
                },
                "fields": {
                  "type": "array",
                  "maxItems": 10000,
                  "uniqueItems": true,
                  "items": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "additionalProperties": true
            },
            "grouping": {
              "type": "object",
              "required": [
                "description"
              ],
              "properties": {
                "description": {
                  "type": "string",
                  "minLength": 1
                },
                "fields": {
                  "type": "array",
                  "maxItems": 10000,
                  "uniqueItems": true,
                  "items": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "additionalProperties": true
            }
          },
          "anyOf": [
            {
              "properties": {
                "source_ids": {
                  "type": "array",
                  "minItems": 1
                }
              }
            },
            {
              "required": [
                "loader_inventory_source_id"
              ],
              "properties": {
                "loader_inventory_source_id": {
                  "type": "string",
                  "minLength": 1
                }
              }
            }
          ],
          "additionalProperties": true
        }
      },
      "preservation": {
        "type": "object",
        "required": [
          "version",
          "handoff",
          "fixity",
          "events",
          "provenance",
          "originals",
          "primary_runtime"
        ],
        "properties": {
          "version": {
            "const": "1.0.0"
          },
          "handoff": {
            "const": "BagIt-1.0"
          },
          "fixity": {
            "const": "sha256"
          },
          "events": {
            "const": "PREMIS-3.0-semantic-mapping"
          },
          "provenance": {
            "const": "PROV-O-JSON-LD"
          },
          "originals": {
            "const": "authoritative-immutable-bytes"
          },
          "primary_runtime": {
            "const": "tablespec-python"
          },
          "qualification": {
            "type": "string",
            "minLength": 1
          },
          "derivations": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "schema_id",
                "source_identity"
              ],
              "properties": {
                "schema_id": {
                  "type": "string",
                  "minLength": 1
                },
                "source_identity": {
                  "type": "string",
                  "minLength": 1
                },
                "qualification": {
                  "type": "string",
                  "minLength": 1
                }
              },
              "additionalProperties": true
            }
          }
        },
        "additionalProperties": true
      },
      "id": {
        "type": "string",
        "minLength": 1
      },
      "version": {
        "type": "string",
        "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"
      },
      "description": {
        "type": "string"
      },
      "family": {
        "type": "object",
        "required": [
          "id",
          "version",
          "label"
        ],
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1
          },
          "version": {
            "type": "string",
            "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"
          },
          "label": {
            "type": "string",
            "minLength": 1
          }
        },
        "additionalProperties": true
      },
      "composition": {
        "type": "object",
        "required": [
          "version",
          "components"
        ],
        "properties": {
          "version": {
            "const": "1.0.0"
          },
          "components": {
            "type": "array",
            "minItems": 1,
            "maxItems": 32,
            "items": {
              "type": "object",
              "required": [
                "id",
                "version",
                "label",
                "checksum"
              ],
              "properties": {
                "id": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9-]*$"
                },
                "version": {
                  "type": "string",
                  "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"
                },
                "label": {
                  "type": "string",
                  "minLength": 1
                },
                "checksum": {
                  "type": "object",
                  "required": [
                    "algorithm",
                    "value"
                  ],
                  "properties": {
                    "algorithm": {
                      "const": "sha256"
                    },
                    "value": {
                      "type": "string",
                      "pattern": "^[a-f0-9]{64}$"
                    }
                  },
                  "additionalProperties": true
                }
              },
              "additionalProperties": true
            }
          }
        },
        "additionalProperties": true
      },
      "generator": {
        "type": "object",
        "required": [
          "id",
          "version"
        ],
        "properties": {
          "id": {
            "type": "string",
            "minLength": 1
          },
          "version": {
            "type": "string",
            "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"
          }
        },
        "additionalProperties": true
      },
      "domain_types": {
        "type": "object",
        "minProperties": 1,
        "propertyNames": {
          "type": "string",
          "pattern": "^[A-Za-z_][A-Za-z0-9_]*$"
        },
        "additionalProperties": {
          "type": "object",
          "properties": {
            "description": {
              "type": "string"
            },
            "sample_generation": {
              "type": "object",
              "required": [
                "method"
              ],
              "properties": {
                "method": {
                  "type": "string",
                  "pattern": "^generate_[A-Za-z0-9_]+$"
                }
              },
              "additionalProperties": true
            },
            "detection": {
              "type": "object"
            }
          },
          "additionalProperties": true
        }
      },
      "scale_presets": {
        "type": "object",
        "additionalProperties": {
          "type": "object",
          "required": [
            "roots",
            "children"
          ],
          "properties": {
            "roots": {
              "type": "object",
              "additionalProperties": {
                "type": "integer",
                "minimum": 0
              }
            },
            "children": {
              "type": "object",
              "additionalProperties": {
                "type": "object",
                "required": [
                  "parent",
                  "per_parent"
                ],
                "properties": {
                  "parent": {
                    "type": "string",
                    "minLength": 1
                  },
                  "per_parent": {
                    "type": "number",
                    "minimum": 0
                  },
                  "distribution": {
                    "enum": [
                      "uniform",
                      "skewed"
                    ]
                  }
                },
                "additionalProperties": true
              }
            }
          },
          "additionalProperties": true
        }
      },
      "sources": {
        "type": "object",
        "minProperties": 1,
        "additionalProperties": {
          "$schema": "https://json-schema.org/draft/2020-12/schema",
          "$id": "urn:umf:dataset-source:1.0.0",
          "type": "object",
          "required": [
            "kind",
            "data_kind"
          ],
          "properties": {
            "kind": {
              "enum": [
                "synthetic",
                "external"
              ]
            },
            "data_kind": {
              "enum": [
                "fabricated",
                "observed",
                "deidentified",
                "unknown"
              ]
            },
            "description": {
              "type": "string"
            },
            "generator": {
              "type": "object",
              "required": [
                "id",
                "version"
              ],
              "properties": {
                "id": {
                  "type": "string",
                  "minLength": 1
                },
                "version": {
                  "type": "string",
                  "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"
                }
              },
              "additionalProperties": true
            },
            "reference": {
              "type": "string",
              "minLength": 1
            },
            "format": {
              "type": "string",
              "minLength": 1
            },
            "revision": {
              "type": "string",
              "minLength": 1
            },
            "checksum": {
              "type": "object",
              "required": [
                "algorithm",
                "value"
              ],
              "properties": {
                "algorithm": {
                  "const": "sha256"
                },
                "value": {
                  "type": "string",
                  "pattern": "^[a-f0-9]{64}$"
                }
              },
              "additionalProperties": true
            },
            "license": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string",
                  "minLength": 1
                },
                "reference": {
                  "type": "string",
                  "minLength": 1
                },
                "redistribution": {
                  "enum": [
                    "allowed",
                    "restricted",
                    "unknown"
                  ]
                },
                "attribution": {
                  "type": "string"
                },
                "notices": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              },
              "additionalProperties": true
            },
            "provenance": {
              "type": "object",
              "properties": {
                "publisher": {
                  "type": "string",
                  "minLength": 1
                },
                "retrieved_at": {
                  "type": "string",
                  "minLength": 1
                },
                "source_ids": {
                  "type": "array",
                  "items": {
                    "type": "string",
                    "minLength": 1
                  }
                },
                "transformations": {
                  "type": "array",
                  "items": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "additionalProperties": true
            }
          },
          "allOf": [
            {
              "if": {
                "properties": {
                  "kind": {
                    "const": "external"
                  }
                }
              },
              "then": {
                "properties": {
                  "reference": {},
                  "format": {}
                },
                "required": [
                  "reference",
                  "format"
                ]
              }
            },
            {
              "if": {
                "properties": {
                  "kind": {
                    "const": "synthetic"
                  }
                }
              },
              "then": {
                "properties": {
                  "generator": {}
                },
                "required": [
                  "generator"
                ]
              }
            }
          ],
          "additionalProperties": true
        }
      },
      "source_bindings": {
        "type": "array",
        "items": {
          "type": "object",
          "required": [
            "schema_id",
            "source_id",
            "role"
          ],
          "properties": {
            "schema_id": {
              "type": "string",
              "minLength": 1
            },
            "source_id": {
              "type": "string",
              "minLength": 1
            },
            "role": {
              "enum": [
                "rows",
                "reference",
                "terminology"
              ]
            }
          },
          "additionalProperties": true
        }
      },
      "schemas": {
        "type": "array",
        "items": {
          "type": "object",
          "required": [
            "id",
            "format",
            "reference"
          ],
          "properties": {
            "id": {
              "type": "string",
              "minLength": 1
            },
            "format": {
              "type": "string",
              "minLength": 1
            },
            "reference": {
              "type": "string",
              "minLength": 1
            }
          },
          "additionalProperties": true
        }
      }
    },
    "additionalProperties": true
  },
  "semantics": "References are data. No imports, fetching, generation, loading or ontology semantics are authorized.",
  "scopes": [
    "document"
  ],
  "capabilities": {
    "validation": "structural",
    "directions": [],
    "evidence": [
      "tests/domain-packs/schema.test.ts"
    ]
  }
}
